import assert from 'node:assert/strict';
globalThis.sampleRate=48000;globalThis.AudioWorkletProcessor=class{constructor(){this.port={onmessage:null,postMessage(){}};}};let Processor;globalThis.registerProcessor=(_,p)=>Processor=p;await import('./cortex-worklet.js');
const send=(p,type,value)=>p.port.onmessage({data:type==='pulse'?{type,event:value}:{type,value}});
function create(limit=8){const p=new Processor();send(p,'params',{active:true,voiceLimit:limit,space:0,output:.38,reverb:0});p.port.onmessage({data:{type:'state',voices:Float32Array.from({length:48},(_,i)=>i%3===0?.5:0)}});return p;}
function block(p,n=1){let peak=0,last;for(let b=0;b<n;b++){last=[new Float32Array(128),new Float32Array(128)];p.process([],[last]);for(const c of last)for(const sample of c){assert.ok(Number.isFinite(sample)&&Math.abs(sample)<=1);peak=Math.max(peak,Math.abs(sample));}}return{peak,last};}
assert.equal(new Processor().voiceLimit,8,'default voice budget is eight');
const idle=create();let calls=0;const sin=Math.sin;Math.sin=x=>{calls++;return sin(x);};block(idle,2);Math.sin=sin;assert.equal(calls,0,'inactive synthesis does not calculate sine waves');
for(const limit of[4,8,16]){const p=create(limit);for(let i=0;i<96;i++){send(p,'pulse',{group:i%16,strength:.65});block(p,4);assert.ok(p.activeVoiceCount()<=limit);}block(p,1000);assert.equal(p.activeVoiceCount(),0,'finished envelopes release voice slots');}
for(let group=0;group<16;group++){const p=create(4);send(p,'pulse',{group,strength:.65});assert.ok(block(p,30).peak>.001,'all sixteen regions can acquire a voice');}
const left=create(4),right=create(4);for(let i=0;i<4;i++){send(left,'pulse',{group:i,strength:.8});send(right,'pulse',{group:i,strength:.8});}block(left,25);block(right,25);send(right,'pulse',{group:15,strength:.8});const reference=block(left).last,stolen=block(right).last;assert.ok(Math.abs(reference[0][0]-stolen[0][0])<.0001,'voice handoff starts from existing waveform without a hard discontinuity');block(right,5);assert.ok(right.slots.some(s=>s.active&&s.group===15));assert.ok(right.activeVoiceCount()<=4);
for(const limit of[4,8,16]){const p=create(limit);send(p,'params',{binaural:true,difference:50,spread:1,droneEnabled:true,output:1});for(let i=0;i<64;i++){send(p,'pulse',{group:i%16,strength:1});block(p,4);assert.ok(p.activeVoiceCount()<=limit);}send(p,'params',{active:false});block(p,100);assert.equal(block(p).peak,0);}
const rapid=create(4);for(let i=0;i<2000;i++){send(rapid,'pulse',{group:i%16,strength:.65});if(i%5===0)block(rapid);assert.ok(rapid.slots.filter(s=>s.pending).length<=4);assert.equal(rapid.slots.length,16);assert.ok(rapid.activeVoiceCount()<=4);}block(rapid,5);assert.ok(rapid.slots.every(s=>s.pending===null));block(rapid,1000);assert.equal(rapid.activeVoiceCount(),0);
const bed=create(16);send(bed,'params',{droneEnabled:true});block(bed,20);assert.equal(bed.activeVoiceCount(),16);send(bed,'params',{voiceLimit:4});block(bed,5);assert.equal(bed.activeVoiceCount(),4);send(bed,'params',{active:false});block(bed,100);assert.equal(block(bed,10).peak,0);assert.equal(bed.activeVoiceCount(),0);
console.log(JSON.stringify({ok:true,defaultVoiceLimit:8,limits:[4,8,16],inactiveSinCalls:0,allRegionsPlayable:true,quietestStealSmoothStart:true,bedSharesBudget:true,highRatePendingBounded:true,binauralPairsBoundedAndSilent:true,finishedSlotsReleased:true,pauseSilence:true},null,2));
